from z3 import *
n=35
x={}
for k in range(1,n+1):
    for i in range(0, 2*n-(k+1)):
        # i+k+1 <= 2n-1 => i <= 2n-k-2, count 2n-k-1 = 69-k
        x[(k,i)]=Bool(f'x_{k}_{i}')
s=Solver()
# exactly one start per k
for k in range(1,n+1):
    vars=[x[(k,i)] for i in range(0,2*n-(k+1))]
    s.add(PbEq([(v,1) for v in vars],1))
# exactly one cover per position
for p in range(2*n):
    vars=[]
    for k in range(1,n+1):
        # p as start i=p if valid, or p as second i=p-(k+1)
        if 0 <= p < 2*n-(k+1): vars.append(x[(k,p)])
        i=p-(k+1)
        if 0 <= i < 2*n-(k+1): vars.append(x[(k,i)])
    s.add(PbEq([(v,1) for v in vars],1))
# symmetry break? fix maybe first occurrence of 35 before symmetric; choose x35 at? None.
# s.add(Or([x[(35,i)] for i in range(0,34)])) always; starts count34
# reverse symmetry break: position of 35 start less than reversal equivalent start? if start i -> reverse start = 70-(i+36)=34-i, so require i <=17 maybe
s.add(Or([x[(35,i)] for i in range(0,18)]))
print('vars',len(x),'constraints',len(s.assertions()))
res=s.check()
print(res)
if res==sat:
    m=s.model()
    seq=[0]*(2*n)
    starts={}
    for (k,i),var in x.items():
        if is_true(m[var]):
            starts[k]=i
            seq[i]=seq[i+k+1]=k
    print(starts)
    print(seq)
    # verify
    from collections import defaultdict
    d=defaultdict(list)
    for idx,v in enumerate(seq): d[v].append(idx)
    print(all(len(d[k])==2 and d[k][1]-d[k][0]==k+1 for k in range(1,n+1)), sorted([p for p,v in enumerate(seq) if v==0])[:10])
